#include "util/util.hpp"
#include "legacy.hpp"
#include <cctype>
namespace util {
std::string slug(const std::string& s) {
    std::string out;
    for (char ch : s) {
        if (ch == ' ') out += '-';
        else out += static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
    }
    return out;
}
std::string shout(const std::string& s) {
    std::string out;
    for (char ch : s) out += static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
    return out;
}
}

